<?php
require dirname(__DIR__).'/includes/bootstrap.php';Auth::start();require BASE_PATH.'/src/PasswordRecovery.php';$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
 $username=trim((string)($_POST['username']??''));if(strlen($username)>64)throw new InvalidArgumentException('Enter your username.');
 if(($_POST['action']??'')==='request'){PasswordRecovery::request($username);$notice='If the account has a recovery email, a code has been sent. Check your inbox and spam folder. Without a recovery email, ask another administrator to reset your password.';}
 else{if(($_POST['new_password']??'')!==($_POST['confirm_password']??''))throw new InvalidArgumentException('Passwords do not match.');PasswordRecovery::reset($username,trim((string)($_POST['code']??'')),(string)($_POST['new_password']??''));$notice='Password reset. You can now sign in with your new password.';}
}catch(Throwable $ex){$error=$ex instanceof InvalidArgumentException?$ex->getMessage():'The request could not be completed. Try again later.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forgot password · Attendance</title><link rel="stylesheet" href="<?= APP_BASE_URL ?>/assets/css/app.css"></head><body class="login-body"><main class="login-card"><h1>Forgot password</h1><?php if($notice): ?><div class="alert ok" role="status"><?= e($notice) ?></div><?php endif; ?><?php if($error): ?><div class="alert err" role="alert"><?= e($error) ?></div><?php endif; ?>
<form method="post"><?= Auth::field() ?><input type="hidden" name="action" value="request"><label>Username<input name="username" maxlength="64" autocomplete="username" required value="<?= e($_POST['username']??'') ?>"></label><button class="btn">Send reset code</button></form>
<details <?= ($_POST['action']??'')==='reset'?'open':'' ?>><summary>I have a reset code</summary><form method="post"><?= Auth::field() ?><input type="hidden" name="action" value="reset"><label>Username<input name="username" maxlength="64" required value="<?= e($_POST['username']??'') ?>"></label><label>Reset code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" required></label><label>New password<input type="password" name="new_password" minlength="12" maxlength="72" autocomplete="new-password" required></label><label>Confirm password<input type="password" name="confirm_password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="btn">Reset password</button></form></details><p><a href="login.php">Back to sign in</a></p></main></body></html>
